css/style.css:
:root {
  --primary: #1D6B3E;
  --primary-light: #3E8C5A;
  --primary-soft: #E8F5EE;
  --primary-dark: #145530;
  --accent: #C8973A;
  --accent-ink: #7A5C00; /* darker gold for TEXT on light bg (4.5:1) — keep --accent for fills/borders */
  --accent-light: rgba(200, 151, 58, 0.15);
  --bg: #F7F4EE;
  --bg-alt: #FAF8F4;
  --text: #1A1A2E;
  --text-secondary: #4A4A5A;
  --text-muted: rgba(45, 45, 45, 0.78); /* was 0.6 (~3.9:1) — now ~6:1 on white */
  --white: #ffffff;
  --border: #E8ECEA;
  --border-light: #F0F2F0;
  --shadow-xs: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-md: 0 8px 30px rgba(0,0,0,0.08);
  --shadow-lg: 0 20px 60px rgba(0,0,0,0.1);
  --shadow-xl: 0 32px 80px rgba(0,0,0,0.12);
  --shadow-glow: 0 0 40px rgba(29,107,62,0.08);
  --radius: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-2xl: 36px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-fast: 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 0.5s cubic-bezier(0.4, 0, 0.2, 1);
  --font-display: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-display);
  color: var(--text);
  background: var(--bg);
  line-height: 1.7;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; height: auto; display: block; }
ul, ol { list-style: none; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section { padding: 6rem 0; }
.section-dark {
  background: linear-gradient(135deg, var(--primary-dark) 0%, var(--primary) 50%, #1a7a45 100%);
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.section-dark::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 20% 20%, rgba(200,151,58,0.1) 0%, transparent 50%),
    radial-gradient(circle at 80% 80%, rgba(255,255,255,0.05) 0%, transparent 50%);
  pointer-events: none;
}

.section-label {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--primary);
}

.section-label::before {
  content: '';
  width: 28px;
  height: 2px;
  background: linear-gradient(90deg, var(--primary), var(--accent));
  border-radius: 1px;
}

.section-label-center {
  justify-content: center;
}

.section-label-center::before {
  background: linear-gradient(90deg, var(--accent), rgba(255,255,255,0.5));
}

.text-center { text-align: center; }

h1, h2, h3, h4 {
  color: var(--primary);
  line-height: 1.2;
}

/* ─── Navigation ─── */
.site-header {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 50;
  background: rgba(255,255,255,0.88);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border-bottom: 1px solid rgba(0,0,0,0.04);
  transition: box-shadow var(--transition);
}

.site-header.scrolled {
  box-shadow: 0 1px 20px rgba(0,0,0,0.06);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 0.65rem 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

.logo-link {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.logo-img {
  width: 44px;
  height: 44px;
  flex-shrink: 0;
  object-fit: cover;
  border-radius: 14px;
  border: 1px solid rgba(29, 107, 62, 0.08);
  box-shadow: 0 2px 8px rgba(29, 107, 62, 0.1);
  transition: transform var(--transition);
}

.logo-link:hover .logo-img {
  transform: scale(1.05);
}

.logo-text { display: none; }
@media (min-width: 640px) {
  .logo-text { display: block; }
}

.logo-title {
  font-size: 1.1rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  color: var(--primary);
  line-height: 1.1;
}

.logo-sub {
  font-size: 0.6rem;
  font-weight: 800;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--accent-ink);
}

.footer-brand-link {
  display: inline-flex;
  align-items: center;
  gap: 0.85rem;
}

.footer-logo-img {
  width: 48px;
  height: 48px;
  object-fit: cover;
  flex-shrink: 0;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.15);
}

.nav-desktop {
  display: none;
  align-items: center;
  gap: 0.25rem;
}

@media (min-width: 768px) {
  .nav-desktop { display: flex; }
}

.nav-link {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: color var(--transition-fast), background var(--transition-fast);
  padding: 0.45rem 0.85rem;
  border-radius: var(--radius);
}

.nav-link:hover {
  color: var(--primary);
  background: var(--primary-soft);
}

.nav-dropdown { position: relative; }

.nav-dropdown:hover .nav-dropdown-menu { display: block; animation: dropdownIn 0.2s ease-out; }

.nav-dropdown-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.45rem 0.85rem;
  border-radius: var(--radius);
  transition: color var(--transition-fast), background var(--transition-fast);
}

.nav-dropdown-toggle:hover { color: var(--primary); background: var(--primary-soft); }

.nav-dropdown-toggle svg { transition: transform var(--transition-fast); }

.nav-dropdown.open .nav-dropdown-toggle svg { transform: rotate(180deg); }

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 0.5rem);
  left: 0;
  min-width: 220px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 0.5rem;
  box-shadow: var(--shadow-lg);
  display: none;
  z-index: 60;
}

.nav-dropdown.open .nav-dropdown-menu { display: block; animation: dropdownIn 0.2s ease-out; }

@keyframes dropdownIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

.nav-dropdown-item {
  display: block;
  padding: 0.6rem 1rem;
  border-radius: var(--radius);
  font-size: 0.85rem;
  color: var(--text-secondary);
  transition: background var(--transition-fast);
}

.nav-dropdown-item:hover { background: var(--primary-soft); color: var(--primary); }

.mobile-dropdown { }

.mobile-dropdown-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.mobile-dropdown-toggle svg { transition: transform var(--transition-fast); }

.mobile-dropdown.open .mobile-dropdown-toggle svg { transform: rotate(180deg); }

.mobile-dropdown-menu {
  display: none;
  padding-left: 1rem;
}

.mobile-dropdown.open .mobile-dropdown-menu { display: block; }

.mobile-dropdown-item {
  display: block;
  padding: 0.5rem 0.75rem;
  font-size: 0.9rem;
  color: var(--text-secondary);
  border-radius: var(--radius);
}

.mobile-dropdown-item:hover { background: var(--primary-soft); color: var(--primary); }

.cicot-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.55rem;
  border-radius: 6px;
  background: linear-gradient(135deg, var(--accent), #D4A84B);
  color: var(--white);
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.05em;
  line-height: 1.3;
  white-space: nowrap;
}

.nav-actions {
  display: none;
  align-items: center;
  gap: 0.75rem;
}

/* Show header LINE CTA from tablet up (was 1024px: 768–1024px had links but no CTA) */
@media (min-width: 768px) {
  .nav-actions { display: flex; }
}

.halal-badge-nav {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid rgba(200, 151, 58, 0.2);
  border-radius: var(--radius);
  padding: 0.4rem 0.65rem;
  background: rgba(255,255,255,0.8);
}

.halal-mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  background: var(--primary);
  color: var(--white);
  font-size: 0.55rem;
  font-weight: 800;
}

.halal-nav-text .halal-top {
  font-size: 0.5rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--accent-ink);
  line-height: 1;
}

.halal-nav-text .halal-bottom {
  font-size: 0.6rem;
  font-weight: 700;
  color: var(--primary);
  line-height: 1.3;
}

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  border: none;
  cursor: pointer;
  font-weight: 700;
  border-radius: var(--radius-lg);
  transition: all var(--transition);
  font-size: 0.875rem;
  padding: 0.75rem 1.5rem;
  letter-spacing: -0.01em;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: 0 2px 8px rgba(29,107,62,0.2);
}

.btn-primary:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(29,107,62,0.25);
}

.btn-outline {
  background: var(--white);
  border: 1.5px solid var(--border);
  color: var(--text-secondary);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: var(--primary-soft);
}

.btn-accent {
  background: var(--white);
  color: var(--text);
  box-shadow: var(--shadow-lg);
}

.btn-accent:hover {
  background: var(--bg);
  transform: translateY(-2px);
  box-shadow: var(--shadow-xl);
}

.btn-gold {
  background: linear-gradient(135deg, var(--accent), #D4A84B);
  color: var(--white);
  box-shadow: 0 4px 16px rgba(200, 151, 58, 0.3);
}

.btn-gold:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(200, 151, 58, 0.4);
}

/* ─── Mobile Menu ─── */
.mobile-toggle {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  background: none;
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  padding: 0.5rem;
  cursor: pointer;
  color: var(--primary);
  transition: all var(--transition-fast);
}

.mobile-toggle:hover {
  border-color: var(--primary);
  background: var(--primary-soft);
}

@media (min-width: 768px) {
  .mobile-toggle { display: none; }
}

.mobile-halal {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid rgba(200, 151, 58, 0.2);
  border-radius: var(--radius);
  padding: 0.3rem 0.5rem;
  background: rgba(255,255,255,0.8);
}

@media (min-width: 768px) {
  .mobile-halal { display: none; }
}

.mobile-halal .halal-mark {
  width: 26px;
  height: 26px;
  font-size: 0.5rem;
  border-radius: 8px;
}

.mobile-halal .halal-top {
  font-size: 0.48rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--accent-ink);
  line-height: 1;
}

.mobile-menu {
  display: none;
  border-top: 1px solid var(--border);
  background: var(--white);
  animation: slideDown 0.25s ease-out;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.mobile-menu.open { display: block; }

.mobile-menu-inner {
  padding: 1rem 1.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.mobile-link {
  display: block;
  padding: 0.7rem 0.85rem;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.95rem;
  transition: background var(--transition-fast);
}

.mobile-link:hover { background: var(--primary-soft); }

.mobile-dropdown-btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 0.7rem 0.85rem;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.95rem;
  background: none;
  border: none;
  cursor: pointer;
  color: var(--primary);
  transition: background var(--transition-fast);
}

.mobile-dropdown-btn:hover { background: var(--primary-soft); }

.mobile-dropdown-btn .arrow {
  font-size: 0.6rem;
  transition: transform var(--transition-fast);
}

.mobile-dropdown-btn[aria-expanded="true"] .arrow {
  transform: rotate(180deg);
}

.mobile-submenu {
  display: none;
  padding-left: 1rem;
  border-left: 2px solid rgba(200, 151, 58, 0.2);
  margin-left: 0.5rem;
}

.mobile-submenu.open { display: block; }

.mobile-submenu a {
  display: block;
  padding: 0.45rem 0.75rem;
  border-radius: var(--radius);
  font-size: 0.85rem;
  transition: background var(--transition-fast);
}

.mobile-submenu a:hover { background: var(--primary-soft); }

.mobile-cta {
  margin-top: 0.75rem;
  padding: 1rem;
  border-radius: var(--radius-xl);
  border: 1px solid rgba(200, 151, 58, 0.15);
  background: linear-gradient(135deg, rgba(200,151,58,0.06) 0%, rgba(29,107,62,0.04) 100%);
}

/* ─── Hero ─── */
.hero {
  padding-top: 7rem;
  background:
    radial-gradient(ellipse at 20% 0%, rgba(200,151,58,0.08), transparent 50%),
    radial-gradient(ellipse at 80% 100%, rgba(29,107,62,0.08), transparent 50%),
    linear-gradient(180deg, var(--bg) 0%, var(--white) 100%);
  overflow: hidden;
}

.hero-grid {
  display: grid;
  gap: 3rem;
  padding: 3rem 1.5rem 5rem;
  max-width: 1200px;
  margin: 0 auto;
}

@media (min-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1.1fr 0.9fr;
    align-items: center;
    gap: 4rem;
  }
}

.hero-content { max-width: 48rem; }

.hero-title {
  margin-top: 1.5rem;
  font-size: 2.75rem;
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: -0.03em;
}

@media (min-width: 768px) {
  .hero-title { font-size: 4rem; }
}

.hero-desc {
  margin-top: 1.75rem;
  font-size: 1.05rem;
  line-height: 1.8;
  opacity: 0.7;
  max-width: 36rem;
}

.hero-stats {
  display: grid;
  gap: 0.75rem;
  margin-top: 2rem;
}

@media (min-width: 640px) {
  .hero-stats { grid-template-columns: repeat(3, 1fr); }
}

.stat-card {
  border: 1px solid var(--border);
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(10px);
  border-radius: var(--radius-lg);
  padding: 1rem 1.25rem;
  transition: all var(--transition);
}

.stat-card:hover {
  border-color: rgba(29,107,62,0.2);
  box-shadow: var(--shadow-sm);
}

.stat-number {
  font-size: 1.6rem;
  font-weight: 900;
  color: var(--text);
  letter-spacing: -0.02em;
}

.stat-label {
  font-size: 0.62rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--text-muted);
  margin-top: 0.15rem;
}

.hero-buttons {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin-top: 2.5rem;
}

@media (min-width: 640px) {
  .hero-buttons { flex-direction: row; }
}

.hero-frame {
  border: 1px solid rgba(200, 151, 58, 0.18);
  background: linear-gradient(135deg, rgba(255,255,255,0.95) 0%, rgba(247,244,238,0.95) 100%);
  box-shadow:
    0 24px 70px -36px rgba(27,67,50,0.35),
    0 0 0 1px rgba(200,151,58,0.05);
  border-radius: var(--radius-2xl);
  padding: 1.5rem;
  position: relative;
  overflow: hidden;
  transition: all var(--transition-slow);
}

.hero-frame:hover {
  box-shadow:
    0 32px 80px -36px rgba(27,67,50,0.4),
    0 0 0 1px rgba(200,151,58,0.1);
  transform: translateY(-4px);
}

@media (min-width: 768px) {
  .hero-frame { padding: 2rem; }
}

.hero-frame-img {
  width: 100%;
  height: 300px;
  object-fit: cover;
  border-radius: 24px;
}

@media (min-width: 768px) {
  .hero-frame-img { height: 420px; }
}

.hero-frame-badge {
  position: absolute;
  top: 2.5rem;
  right: 2.5rem;
}

.hero-frame-grid {
  display: grid;
  gap: 1rem;
  margin-top: 1.5rem;
}

@media (min-width: 768px) {
  .hero-frame-grid { grid-template-columns: 1fr 1fr; }
}

/* ─── Cards ─── */
.card {
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  background: var(--white);
  transition: all var(--transition);
  overflow: hidden;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: rgba(29,107,62,0.15);
}

.card-body { padding: 2rem; }
.card-sm { padding: 1.75rem; }

.card-kicker {
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent-ink);
}

.card-title {
  font-size: 1.3rem;
  font-weight: 800;
  margin-top: 0.75rem;
  letter-spacing: -0.01em;
}

.card-desc {
  font-size: 0.88rem;
  line-height: 1.75;
  color: var(--text-muted);
  margin-top: 0.65rem;
}

.card-price {
  font-size: 1.4rem;
  font-weight: 900;
  color: var(--primary);
  margin-top: 0.5rem;
}

.card-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.85rem;
  font-weight: 700;
  margin-top: 1.25rem;
  color: var(--primary);
  transition: all var(--transition-fast);
}

.card-link:hover { gap: 0.55rem; opacity: 0.8; }

.panel-gold {
  border: 1px solid rgba(200, 151, 58, 0.15);
  background: linear-gradient(135deg, rgba(247,244,238,0.6) 0%, rgba(255,255,255,0.95) 100%);
}

.benefit-card {
  border-radius: var(--radius-xl);
  background: var(--white);
  border: 1px solid var(--border);
  padding: 2rem;
  transition: all var(--transition);
}

.benefit-card:hover {
  border-color: rgba(29,107,62,0.2);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.benefit-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: var(--radius);
  background: var(--primary-soft);
  color: var(--primary);
  margin-bottom: 0.85rem;
}

/* ─── Grids ─── */
.grid-2 { display: grid; gap: 1.5rem; }
.grid-3 { display: grid; gap: 1.5rem; }
.grid-4 { display: grid; gap: 1.5rem; }

@media (min-width: 768px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
}

/* ─── Breadcrumb ─── */
.breadcrumb {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--text-muted);
  margin-bottom: 2rem;
}

.breadcrumb a { transition: color var(--transition-fast); }
.breadcrumb a:hover { color: var(--primary); }
.breadcrumb span { margin: 0 0.5rem; opacity: 0.5; }

/* ─── Page Header ─── */
.page-header {
  padding-top: 8rem;
  padding-bottom: 3rem;
  background:
    radial-gradient(ellipse at 30% 0%, rgba(200,151,58,0.06), transparent 60%),
    linear-gradient(180deg, var(--bg) 0%, var(--white) 100%);
}

.page-header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1.5rem 3rem;
}

/* Featured snack-box content */
.snack-hero-cta {
  padding: 0 0 2rem;
  background: var(--white);
}

.snack-hero-cta-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  max-width: 1080px;
  margin: 0 auto;
  padding: 1rem 1.25rem;
  color: var(--primary);
  background: var(--primary-soft);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
}

.snack-hero-cta-inner > span {
  font-size: 0.9rem;
