}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 1rem;
  font-weight: 700;
  color: var(--text);
  text-align: left;
  font-family: inherit;
  line-height: 1.5;
}

.faq-question .arrow {
  font-size: 0.75rem;
  flex-shrink: 0;
  transition: transform var(--transition);
  color: var(--primary);
}

.faq-item.open .faq-question .arrow {
