/* Catering landing page: keep the decision path compact and visual. */
.catering-hero .container { max-width: 1240px; }

.catering-hero-card {
  overflow: hidden;
  border: 1px solid rgba(29,107,62,0.12);
  border-radius: var(--radius-xl);
  background: var(--white);
  box-shadow: var(--shadow-lg);
}

.catering-hero-image { position: relative; }
.catering-hero-image img {
  display: block;
  width: 100%;
  height: 310px;
  object-fit: cover;
}
.catering-hero-badge {
  position: absolute;
  left: 1.25rem;
  bottom: 1.25rem;
  padding: 0.45rem 0.7rem;
  border-radius: 999px;
  background: rgba(20,56,35,0.9);
