.catering-trust {
  border-bottom: 1px solid var(--border);
  background: var(--white);
}
.catering-trust-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
  padding-top: 1.4rem;
  padding-bottom: 1.4rem;
}
.catering-trust-grid > div {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  padding: 0.25rem 1.25rem;
  border-right: 1px solid var(--border);
}
.catering-trust-grid > div:last-child { border-right: 0; }
.catering-trust-grid strong { color: var(--primary); font-size: 1rem; font-weight: 850; }
