  min-width: 0;
}
.catering-service-card > img { height: 210px !important; }
.catering-service-card > div:last-child {
  display: flex;
  flex: 1;
  flex-direction: column;
}
.catering-service-card > div:last-child > a { align-self: flex-start; margin-top: auto !important; }

@media (max-width: 1023px) {
  .catering-service-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .catering-service-card:last-child { grid-column: 1 / -1; }
}

@media (max-width: 767px) {
  .catering-hero-image img { height: 245px; }
  .catering-hero-card-body { padding: 1.35rem 1.25rem 1.5rem; }
  .catering-trust-grid { grid-template-columns: 1fr; gap: 0.5rem; }
  .catering-trust-grid > div { border-right: 0; border-bottom: 1px solid var(--border); padding: 0.7rem 0; }
  .catering-trust-grid > div:last-child { border-bottom: 0; }
  .catering-service-grid { grid-template-columns: 1fr; }
  .catering-service-card:last-child { grid-column: auto; }
}

.review-card {
