/* ─── Client Logo Carousel ─── */
.client-logos {
  padding: 3.5rem 0;
  background: var(--white);
  overflow: hidden;
  border-top: 1px solid var(--border-light);
  border-bottom: 1px solid var(--border-light);
}

.client-logos-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.client-logos-header {
  text-align: center;
  margin-bottom: 2rem;
}

.client-logos-title {
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--text-muted);
  opacity: 0.55;
}

.logo-carousel {
  overflow: hidden;
  position: relative;
}

.logo-carousel::before,
.logo-carousel::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 60px;
  z-index: 2;
  pointer-events: none;
}

.logo-carousel::before {
  left: 0;
  background: linear-gradient(90deg, var(--white), transparent);
}

.logo-carousel::after {
  right: 0;
  background: linear-gradient(-90deg, var(--white), transparent);
}

.logo-track {
  display: flex;
  gap: 2.5rem;
  align-items: center;
  animation: scrollLogos 35s linear infinite;
  width: max-content;
}

.logo-carousel:hover .logo-track {
  animation-play-state: paused;
}

.logo-slide {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 48px;
}

.logo-slide img {
  max-height: 100%;
  width: auto;
  max-width: 120px;
  object-fit: contain;
  opacity: 0.4;
  filter: grayscale(1);
  transition: all var(--transition);
}

.logo-slide img:hover {
  opacity: 0.85;
  filter: grayscale(0);
}

@keyframes scrollLogos {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@media (max-width: 640px) {
  .client-logos { padding: 2rem 0; }
  .client-logos-title { font-size: 0.55rem; }
  .logo-track { gap: 1.5rem; animation-duration: 25s; }
  .logo-slide { height: 36px; }
  .logo-slide img { max-width: 80px; }
  .logo-carousel::before,
  .logo-carousel::after { width: 24px; }
}

/* ─── Budget Calculator ─── */
.calculator-section {
  max-width: 42rem;
  margin: 3rem auto 0;
}

.calculator-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-md);
}

.calculator-header {
  background: linear-gradient(135deg, var(--primary-soft) 0%, var(--white) 100%);
  padding: 2rem 2rem 1.5rem;
  border-bottom: 1px solid var(--border-light);
}

.calculator-body {
  padding: 2rem;
}

.calc-row {
  display: grid;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

@media (min-width: 640px) {
  .calc-row {
    grid-template-columns: 1fr auto 1fr;
    align-items: end;
  }
}

.calc-field {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.calc-label {
  font-size: 0.85rem;
  font-weight: 800;
  color: var(--text);
  letter-spacing: 0.01em;
}

.calc-input-wrap {
  position: relative;
}

.calc-input {
  width: 100%;
  padding: 0.85rem 4.5rem 0.85rem 1rem;
  border: 2px solid var(--border);
  border-radius: var(--radius-lg);
  font-size: 1.25rem;
  font-weight: 800;
  font-family: inherit;
  color: var(--text);
  background: var(--bg-alt);
  transition: all var(--transition-fast);
  outline: none;
}

.calc-input:focus {
  border-color: var(--primary);
  background: var(--white);
  box-shadow: 0 0 0 4px rgba(29,107,62,0.08);
}

.calc-input-budget {
  padding-left: 2.5rem;
}

.calc-unit {
  position: absolute;
  right: 1rem;
  top: 50%;
  transform: translateY(-50%);
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-muted);
  pointer-events: none;
}

.calc-unit-left {
  right: auto;
  left: 1rem;
}

.calc-range {
  width: 100%;
  height: 6px;
  -webkit-appearance: none;
  appearance: none;
  background: var(--border);
  border-radius: 3px;
  outline: none;
  cursor: pointer;
}

.calc-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  border: 3px solid var(--white);
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
  transition: transform var(--transition-fast);
}

.calc-range::-webkit-slider-thumb:hover {
  transform: scale(1.15);
}

.calc-range::-moz-range-thumb {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: var(--primary);
  cursor: pointer;
  border: 3px solid var(--white);
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.calc-range-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.65rem;
  font-weight: 700;
  color: var(--text-muted);
  opacity: 0.5;
}

.calc-divider {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 900;
  color: var(--accent-ink);
  padding: 0 0.5rem 0.35rem;
}

@media (max-width: 639px) {
  .calc-divider { display: none; }
}

.calc-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-top: 0.25rem;
}

.calc-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.35rem 0.75rem;
  border: 1.5px solid var(--border);
  border-radius: 999px;
  background: var(--white);
  font-size: 0.82rem;
  font-weight: 700;
  font-family: inherit;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.calc-chip:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: var(--primary-soft);
}

.calc-chip.active {
  border-color: var(--primary);
  background: var(--primary);
  color: var(--white);
  box-shadow: 0 2px 8px rgba(29,107,62,0.2);
}

.calc-result {
  text-align: center;
  background: var(--primary-soft);
  border: 2px dashed rgba(29,107,62,0.15);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}

.calc-result-label {
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--text-muted);
}

.calc-result-amount {
  font-size: 2.5rem;
  font-weight: 900;
  color: var(--primary);
  line-height: 1.2;
  margin-top: 0.25rem;
  letter-spacing: -0.02em;
}

.calc-result-note {
  font-size: 0.75rem;
  opacity: 0.5;
  margin-top: 0.25rem;
}

.calc-cta {
  width: 100%;
  padding: 1rem;
  font-size: 1.05rem;
  justify-content: center;
}

@media (max-width: 480px) {
  .calculator-header { padding: 1.5rem 1.25rem; }
  .calculator-body { padding: 1.25rem; }
  .calc-input { font-size: 1.05rem; padding: 0.7rem 3.5rem 0.7rem 0.75rem; }
  .calc-input-budget { padding-left: 2rem; }
  .calc-result-amount { font-size: 2rem; }
  .calc-chip { font-size: 0.72rem; padding: 0.25rem 0.55rem;   }
}


/* ─── Menu Cards ─── */
.menu-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
  margin-bottom: 1.25rem;
}

.menu-card-image {
  width: 100%;
  aspect-ratio: 2/1;
  overflow: hidden;
}

.menu-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.menu-card-body {
  padding: 1.5rem;
}

.menu-card-title {
  font-size: 1.1rem;
  font-weight: 900;
  color: var(--text);
  margin-bottom: 0.3rem;
}

.menu-item-list {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.menu-item {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  font-size: 0.88rem;
  line-height: 1.7;
  color: var(--text);
}

.menu-item-name {
  flex-shrink: 0;
  font-weight: 500;
}

.menu-item-dots {
  flex: 1;
  min-width: 1rem;
  border-bottom: 1px dotted var(--border);
}

.menu-tier {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

/* ─── Tier Reference ─── */
.tier-reference {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
  max-width: 36rem;
  margin: 0 auto;
}

.tier-ref-item {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.6rem 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  box-shadow: var(--shadow-sm);
}

.tier-ref-price {
  font-size: 1.1rem;
  font-weight: 900;
  color: var(--primary);
  line-height: 1;
}

.tier-ref-label {
  font-size: 0.75rem;
  font-weight: 700;
  color: var(--text);
}

.tier-ref-note {
  font-size: 0.65rem;
  color: var(--text-muted);
  font-weight: 600;
}

/* ─── Food Gallery Carousel ─── */
.food-gallery {
  margin-top: 3rem;
}

.food-gallery-title {
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--text);
  margin-bottom: 1.25rem;
  text-align: center;
}

.food-carousel {
  overflow: hidden;
  position: relative;
}

.food-carousel::before,
.food-carousel::after {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50px;
  z-index: 2;
  pointer-events: none;
}

.food-carousel::before {
  left: 0;
  background: linear-gradient(90deg, var(--bg), transparent);
}

.food-carousel::after {
  right: 0;
  background: linear-gradient(-90deg, var(--bg), transparent);
}

.food-track {
  display: flex;
  gap: 1rem;
  animation: scrollFood 40s linear infinite;
  width: max-content;
}

.food-carousel:hover .food-track {
  animation-play-state: paused;
}

.food-slide {
  flex-shrink: 0;
  width: 260px;
  aspect-ratio: 4/3;
  border-radius: var(--radius);
  overflow: hidden;
}

.food-slide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
}

.food-slide img:hover {
  transform: scale(1.08);
}

@keyframes scrollFood {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ─── FAQ Section ─── */
.faq-section {
  margin-top: 3rem;
}

.faq-section .faq-answer {
  display: block;
}

.faq-section .faq-question {
  cursor: default;
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--primary);
  margin-bottom: 0.3rem;
}

.faq-section .faq-item {
  padding: 1rem 1.25rem;
}

.faq-heading {
  font-size: 1.3rem;
  font-weight: 900;
  color: var(--text);
  margin-bottom: 1.25rem;
  text-align: center;
}

@media (max-width: 640px) {
  .menu-card-body { padding: 1.25rem; }
  .tier-reference { gap: 0.4rem; }
  .tier-ref-item { padding: 0.4rem 0.75rem; }
  .tier-ref-price { font-size: 0.95rem; }
  .tier-ref-label { font-size: 0.65rem; }
  .tier-ref-note { font-size: 0.6rem; }
  .menu-tier { font-size: 0.6rem; padding: 0.15rem 0.5rem; }
  .food-gallery { margin-top: 2rem; }
  .food-gallery-title { font-size: 1.05rem; }
  .food-slide { width: 180px; }
  .food-carousel::before,
  .food-carousel::after { width: 24px; }
  .faq-section { margin-top: 2rem; }
  .faq-heading { font-size: 1.05rem; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
  .logo-track,
  .food-track {
    animation: none !important;
    transform: none !important;
  }
}

/* ─── Sticky LINE CTA (mobile) ─── */
.sticky-line-cta {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 999;
  display: none;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  background: var(--accent);
  color: var(--white);
  font-weight: 800;
  font-size: 1.02rem;
  padding: 0.9rem 1rem;
  text-align: center;
  box-shadow: 0 -2px 12px rgba(0, 0, 0, 0.15);
  -webkit-tap-highlight-color: transparent;
}

.sticky-line-cta:hover,
.sticky-line-cta:focus,
.sticky-line-cta:active {
  color: var(--white);
  text-decoration: none;
}

@media (max-width: 768px) {
  body {
    padding-bottom: calc(3.6rem + env(safe-area-inset-bottom, 0px));
  }

  .sticky-line-cta {
    display: flex;
    padding-bottom: calc(0.9rem + env(safe-area-inset-bottom, 0px));
  }
}

/* ─── Related Article Cards ─── */
.related-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.25rem;
}
.related-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 1rem;
  padding: 1.75rem;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  text-decoration: none;
  overflow: hidden;
  transition: all var(--transition);
}
.related-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--accent), var(--primary-light));
  opacity: 0;
  transition: opacity var(--transition);
}
.related-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: rgba(200, 151, 58, 0.35);
}
.related-card:hover::before {
  opacity: 1;
}
.related-card-icon {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--primary-soft);
  border-radius: var(--radius);
  color: var(--primary);
  transition: transform var(--transition), background var(--transition);
}
.related-card:hover .related-card-icon {
  transform: scale(1.08);
  background: var(--accent-light);
}
.related-card-tag {
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent-ink);
  margin-top: 0.5rem;
}
.related-card-title {
  font-size: 1rem;
  font-weight: 800;
  color: var(--primary);
  line-height: 1.4;
  margin-top: 0.35rem;
}
.related-card-desc {
  font-size: 0.82rem;
  line-height: 1.7;
  color: var(--text-muted);
  margin-top: 0.4rem;
}
.related-card-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: auto;
  font-size: 0.82rem;
  font-weight: 800;
  color: var(--primary);
}
.related-card-cta svg {
  transition: transform var(--transition);
}
.related-card:hover .related-card-cta svg {
  transform: translateX(4px);
}

@media (max-width: 900px) {
  .related-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 560px) {
  .related-grid { grid-template-columns: 1fr; }
}

