          state.selected[id] = (state.selected[id]||0)+1;
          renderResults(); updateSummary();
        } else if(act==='dec'){
          state.selected[id] = (state.selected[id]||0)-1;
          if(state.selected[id]<=0){ delete state.selected[id]; delete state.selectedToppings[id]; delete state.selectedMeats[id]; }
          renderResults(); updateSummary();
