/* EED HALAL — popular-menu hydrate (SEO-safe)
 * Keeps static HTML for crawlers (Google/AI) — only enhances for humans with JS.
 * Reads EED_MENUS + planner-overrides.json + localStorage and re-renders:
 *  - #popularMenuGrid  (16 cards)
 *  - #fullMenuBody     (full categorized menu list)
 * If data is available. If JS fails or file missing, static HTML remains.
 */
(function(){
  'use strict';
  var GRID_ID = 'popularMenuGrid';
  var FULL_ID = 'fullMenuBody';
  var LS_SELLING = 'eed_selling_v1';
  var LS_MINS = 'eed_mins_v1';
  var LS_IMAGES = 'eed_images_v1';
  var LS_NAMES = 'eed_names_v1';
  var LS_CATEGORIES = 'eed_categories_v1';
  var LS_DELETED = 'eed_deleted_v1';
  var LS_NEW_MENUS = 'eed_new_menus_v1';
  var LS_TOPPINGS = 'eed_toppings_v1';

  // Popular menu IDs in order — edit here to control what shows on popular-menu.html
  var POPULAR_IDS = [16,1,2,3,4,17,5,24,6,18,31,8,14,19,38,37];

  // Category config for full menu — order = display order
  var CATS_TH = [
    { key: 'ข้าวผัด',  emoji: '🍳', label: 'เมนูข้าวผัด' },
    { key: 'ข้าวราดแกง', emoji: '🍛', label: 'เมนูข้าวราดแกง' },
    { key: 'เส้น',     emoji: '🍝', label: 'เมนูเส้น' },
    { key: 'อาหารอินเดีย',  emoji: '🍛', label: 'เมนูอาหารอินเดีย' },
    { key: 'พรีเมียม', emoji: '👑', label: 'เมนูพรีเมียม' }
  ];
  var CATS_EN = [
    { key: 'ข้าวผัด',  emoji: '🍳', label: 'Fried Rice Dishes' },
    { key: 'ข้าวราดแกง', emoji: '🍛', label: 'Rice with Curry & Toppings' },
    { key: 'เส้น',     emoji: '🍝', label: 'Noodle Dishes' },
    { key: 'อาหารอินเดีย',  emoji: '🍛', label: 'Indian Dishes' },
    { key: 'พรีเมียม', emoji: '👑', label: 'Premium Sets' }
  ];

  function escapeHtml(s){
    return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  function isEnPath(){
    return window.location.pathname.indexOf('/en/')===0 || window.location.pathname.indexOf('/en')!==-1;
  }
  function fixImagePath(src){
    if(!src) return src;
    if(isEnPath() && src.indexOf('img/')===0) return '../' + src;
    return src;
  }

  function applyCatalog(data){
    if(!data || typeof data!=='object' || typeof EED_MENUS==='undefined') return;
    var fields={prices:'price',mins:'minPerMenu',images:'image',names:'name',categories:'category'};
    Object.keys(fields).forEach(function(key){
      var values=data[key];
      if(!values || typeof values!=='object') return;
      Object.keys(values).forEach(function(id){
        for(var i=0;i<EED_MENUS.length;i++){
          if(String(EED_MENUS[i].id)!==String(id)) continue;
          var value=values[id];
          if(key==='prices') value=parseFloat(value);
          if(key==='mins') value=parseInt(value,10);
          if(value!==undefined && value!==null && value!=='') EED_MENUS[i][fields[key]]=value;
          break;
        }
      });
    });
    if(Array.isArray(data.toppings)) EED_MENUS.forEach(function(menu){ menu.toppings=data.toppings.map(function(t){ return {name:String(t.name),price:parseInt(t.price,10)||0}; }); });
    if(Array.isArray(data.deleted)) EED_MENUS=EED_MENUS.filter(function(menu){ return data.deleted.indexOf(menu.id)===-1 && data.deleted.indexOf(String(menu.id))===-1; });
    if(Array.isArray(data.newMenus)) data.newMenus.forEach(function(menu){
      if(!menu || menu.id===undefined || !menu.name || EED_MENUS.some(function(item){ return String(item.id)===String(menu.id); })) return;
      EED_MENUS.push({id:menu.id,name:String(menu.name),price:parseFloat(menu.price)||0,category:String(menu.category||'ข้าวราดแกง'),image:String(menu.image||''),desc:String(menu.desc||''),badge:String(menu.badge||''),minPerMenu:parseInt(menu.minPerMenu,10)||5,toppings:Array.isArray(data.toppings)?data.toppings.map(function(t){ return {name:String(t.name),price:parseInt(t.price,10)||0}; }):[]});
    });
  }

  function applyOverrides(){
    try{ applyCatalog({prices:JSON.parse(localStorage.getItem(LS_SELLING)||'null'),mins:JSON.parse(localStorage.getItem(LS_MINS)||'null'),images:JSON.parse(localStorage.getItem(LS_IMAGES)||'null'),names:JSON.parse(localStorage.getItem(LS_NAMES)||'null'),categories:JSON.parse(localStorage.getItem(LS_CATEGORIES)||'null'),deleted:JSON.parse(localStorage.getItem(LS_DELETED)||'null'),newMenus:JSON.parse(localStorage.getItem(LS_NEW_MENUS)||'null'),toppings:JSON.parse(localStorage.getItem(LS_TOPPINGS)||'null')}); }catch(e){}
  }

  function loadServerOverrides(cb){
    if(location.protocol==='file:'){ if(cb) cb(); return; }
    var urls=['/data/planner-overrides.json','data/planner-overrides.json','./data/planner-overrides.json','../data/planner-overrides.json'];
    var i=0;
    function next(){
      if(i>=urls.length){ if(cb) cb(); return; }
      fetch(urls[i++]+'?t='+Date.now(),{cache:'no-store'}).then(function(r){
        if(!r.ok) throw new Error('not ok');
        return r.json();
      }).then(function(data){
        try{ applyCatalog(data); }catch(e){}
        if(cb) cb();
      }).catch(next);
    }
    next();
  }

  /* ─── Popular Grid ─── */
  function getPopularMenus(){
    if(typeof EED_MENUS==='undefined' || !Array.isArray(EED_MENUS) || !EED_MENUS.length) return [];
    var hasPopularFlag = EED_MENUS.some(function(m){ return m.popular === true; });
    if(hasPopularFlag){
      var flagged = EED_MENUS.filter(function(m){ return m.popular === true; });
      flagged.sort(function(a,b){
        if(a.popularRank!==undefined && b.popularRank!==undefined) return a.popularRank - b.popularRank;
        if(a.popularRank!==undefined) return -1;
        if(b.popularRank!==undefined) return 1;
        var aScore = (a.badge && a.badge.indexOf('Best')!==-1 ? 0 : a.badge==='ใหม่' ? 1 : 2);
        var bScore = (b.badge && b.badge.indexOf('Best')!==-1 ? 0 : b.badge==='ใหม่' ? 1 : 2);
        if(aScore!==bScore) return aScore-bScore;
        return a.price - b.price;
      });
      return flagged.slice(0,16);
    }
    var byId = {};
    EED_MENUS.forEach(function(m){ byId[String(m.id)] = m; });
    var list = [];
    POPULAR_IDS.forEach(function(id){
      if(byId[String(id)]) list.push(byId[String(id)]);
    });
    if(list.length < 12){
      var remaining = EED_MENUS.filter(function(m){ return list.indexOf(m)===-1; })
        .sort(function(a,b){
          var aScore = (a.badge && a.badge.indexOf('Best')!==-1 ? 0 : a.badge==='ใหม่' ? 1 : 2);
          var bScore = (b.badge && b.badge.indexOf('Best')!==-1 ? 0 : b.badge==='ใหม่' ? 1 : 2);
          if(aScore!==bScore) return aScore-bScore;
          return a.price - b.price;
        });
      list = list.concat(remaining.slice(0, 16 - list.length));
    }
    return list.slice(0, 16);
  }

  function renderGrid(){
    var grid = document.getElementById(GRID_ID);
    if(!grid) return;
    if(typeof EED_MENUS==='undefined') return;
    var menus = getPopularMenus();
    if(!menus.length) return;
    try{
      var html = menus.map(function(m){
        var badge = m.badge ? '<span style="background:var(--accent);color:var(--white);font-size:0.65rem;font-weight:700;padding:0.2rem 0.55rem;border-radius:999px;vertical-align:middle">'+escapeHtml(m.badge)+'</span>' : '';
        return '<div style="background:var(--white);border-radius:var(--radius-xl);box-shadow:var(--shadow-sm);overflow:hidden;display:flex;flex-direction:column">'
          + '<div style="aspect-ratio:4/3;overflow:hidden">'
          + '<img src="'+escapeHtml(fixImagePath(m.image))+'" alt="'+escapeHtml(m.name)+' EED HALAL" style="width:100%;height:100%;object-fit:cover;display:block" loading="lazy" onerror="this.style.display=\'none\'">'
          + '</div>'
          + '<div style="padding:1.25rem 1.25rem 1.5rem;display:flex;flex-direction:column;gap:0.4rem;flex:1">'
          + '<h4 style="font-size:1.25rem;font-weight:900;color:var(--text);margin:0">'+escapeHtml(m.name)+' '+badge+'</h4>'
          + '<p style="font-size:0.8rem;line-height:1.7;opacity:0.7;color:var(--text);margin:0">'+escapeHtml(m.desc||'')+'</p>'
          + '</div>'
          + '</div>';
      }).join('');
      grid.innerHTML = html;
      grid.setAttribute('data-hydrated','true');
      try{ document.dispatchEvent(new CustomEvent('popularMenuHydrated', {detail:{count:menus.length}})); }catch(e){}
    }catch(e){
      console.warn('[popular-menu-hydrate] grid failed, keeping static:', e);
    }
  }

  /* ─── Full Menu ─── */
  function renderFullMenu(){
    var body = document.getElementById(FULL_ID);
    if(!body) return;
    if(typeof EED_MENUS==='undefined') return;
    var cats = isEnPath() ? CATS_EN : CATS_TH;
    try{
      var html = cats.map(function(cat){
        var items = EED_MENUS.filter(function(m){ return m.category===cat.key; });
        if(!items.length) return '';
        var dots = '<span class="menu-item-dots"></span>';
        var itemHtml = items.map(function(m){
          return '<div class="menu-item"><span class="menu-item-name">'+escapeHtml(cat.emoji)+' '+escapeHtml(m.name)+'</span>'+dots+'</div>';
        }).join('');
        return '<div style="margin-bottom:2.5rem">'
          + '<h4 style="font-size:1.15rem;font-weight:900;color:var(--primary);margin:0 0 1rem">'+escapeHtml(cat.emoji)+' '+escapeHtml(cat.label)+'</h4>'
          + '<div class="menu-item-list" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:0.35rem 1.25rem">'
          + itemHtml
          + '</div></div>';
      }).join('');
      body.innerHTML = html;
      body.setAttribute('data-hydrated','true');
    }catch(e){
      console.warn('[popular-menu-hydrate] full menu failed, keeping static:', e);
    }
  }

  function init(){
    if(typeof EED_MENUS==='undefined') return;
    applyOverrides();
    var rendered = false;
    function doRender(){
      if(rendered) return;
      rendered = true;
      renderGrid();
      renderFullMenu();
    }
    doRender();
    loadServerOverrides(function(){
      doRender();
      renderGrid();
      renderFullMenu();
    });
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

js/snack-builder.js:
/* EED HALAL — Snack Box Builder
 * Interactive tool for customers to build their own snack box.
 * Reads EED_SNACK_MENUS from snack-data.js and renders a picker UI.
 * Sends summary to LINE via pre-filled message.
 */
(function(){
  'use strict';

  var LINE_URL = 'https://lin.ee/CfvqJTd';

  function esc(s){
    return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  }

  function $(id){ return document.getElementById(id); }

  /* ─── State ─── */
  var state = {
    quantity: 30,
    savory: [],   // selected savory ids (optional, +40baht each)
    sweet: [],    // selected sweet ids (max 1)
    juice: [],    // selected juice ids (max 1)
    addon: 'water', // selected drink addon id
    deliveryZone: ''
  };

  /* ─── Get items by category ─── */
  function getMenus(cat){
    if(typeof EED_SNACK_MENUS==='undefined') return [];
    return EED_SNACK_MENUS.filter(function(m){ return m.category===cat; });
  }

  function getAddons(){
    if(typeof EED_SNACK_ADDONS==='undefined') return [];
    return EED_SNACK_ADDONS;
  }

  function getAddonById(id){
    var addons = getAddons();
    for(var i=0;i<addons.length;i++){
      if(addons[i].id===id) return addons[i];
    }
    return addons[0];
  }

  function getItemById(id){
    if(typeof EED_SNACK_MENUS==='undefined') return null;
    for(var i=0;i<EED_SNACK_MENUS.length;i++){
      if(EED_SNACK_MENUS[i].id===id) return EED_SNACK_MENUS[i];
    }
    return null;
  }

  /* ─── Price calc ─── */
  function calcPricePerBox(){
    var addon = getAddonById(state.addon);
    var savoryCost = 0;
    for(var i=0;i<state.savory.length;i++){
      var m = getItemById(state.savory[i]);
      if(m) savoryCost += m.price;
    }
    return 40 + savoryCost + (addon ? addon.price : 0);
  }

  function calcTotal(){
    return calcPricePerBox() * state.quantity + getShipping().fee;
  }

  function getShipping(){
    var zones=typeof EED!=='undefined' && EED.shippingZones ? EED.shippingZones : {};
    var thresholds=typeof EED!=='undefined' && EED.shippingZoneFreeThresholds ? EED.shippingZoneFreeThresholds : {};
    var zone=zones[state.deliveryZone];
    if(!zone) return {fee:0,text:'เลือกเขตเพื่อเช็กค่าส่ง',unknown:true};
    var freeFrom=parseInt(thresholds[state.deliveryZone],10)||0;
    if(freeFrom && state.quantity>=freeFrom) return {fee:0,text:'ฟรี ('+freeFrom+'+ กล่อง)',unknown:false};
    var carMin=typeof EED!=='undefined' ? parseInt(EED.shippingCarMinQty,10)||40 : 40;
    var fee=state.quantity>carMin ? Number(zone.car)||0 : Number(zone.moto)||0;
    return {fee:fee,text:fee.toLocaleString('th-TH')+' บาท',unknown:false};
  }

  function getMinimumOrder(){
    return typeof EED !== 'undefined' && EED.snackMinOrder ? parseInt(EED.snackMinOrder,10) || 30 : 30;
  }

  function renderDeliveryZones(){
    var select=$('sbDeliveryZone');
    if(!select) return;
    var zones=typeof EED!=='undefined' && EED.shippingZones ? EED.shippingZones : {};
    select.innerHTML='<option value="">เลือกเขตจัดส่งเพื่อคำนวณ</option>'+Object.keys(zones).map(function(id){
      return '<option value="'+esc(id)+'"'+(state.deliveryZone===id?' selected':'')+'>'+esc(zones[id].label)+'</option>';
    }).join('');
    select.onchange=function(){ state.deliveryZone=this.value; updateSummary(); };
  }

  /* ─── Render checkboxes (generic) ─── */
  function renderCategory(catId, containerId, stateArr, maxCount, updateFn){
    var container = $(containerId);
    if(!container) return;
    var items = getMenus(catId);
    var html = '';
    for(var i=0;i<items.length;i++){
      var m = items[i];
      var checked = stateArr.indexOf(m.id)!==-1;
      html += '<label class="sb-check-item'+(checked?' active':'')+'" data-id="'+esc(m.id)+'">';
      html += '<input type="checkbox" value="'+esc(m.id)+'"'+(checked?' checked':'')+' class="sb-check-input">';
      html += '<span class="sb-check-box"></span>';
      html += '<span class="sb-check-name">'+esc(m.name)+'</span>';
      html += '</label>';
    }
    container.innerHTML = html;

    var inputs = container.querySelectorAll('.sb-check-input');
    for(var j=0;j<inputs.length;j++){
      inputs[j].addEventListener('change', function(){
        var id = this.value;
        /* determine which state key */
        var key;
        if(containerId==='sbSavoryList') key='savory';
        else if(containerId==='sbJuiceList') key='juice';
        else key='sweet';
        if(this.checked){
          if(state[key].indexOf(id)===-1) state[key].push(id);
        } else {
          state[key] = state[key].filter(function(x){ return x!==id; });
        }
        /* enforce max */
        if(maxCount>0 && state[key].length>maxCount){
          var removed = state[key].shift();
          var remCb = container.querySelector('input[value="'+removed+'"]');
          if(remCb){ remCb.checked=false; remCb.parentElement.classList.remove('active'); }
        }
        updateFn();
        updateSummary();
      });
    }
    updateFn();
  }

  /* ─── Render savory (optional, +40 baht) ─── */
  function renderSavory(){
    renderCategory('savory','sbSavoryList',state.savory,0,updateSavoryCount);
  }

  function updateSavoryCount(){
    var el = $('sbSavoryCount');
    if(el) el.textContent = state.savory.length;
    var items = document.querySelectorAll('#sbSavoryList .sb-check-item');
    for(var i=0;i<items.length;i++){
      var id = items[i].getAttribute('data-id');
      if(state.savory.indexOf(id)!==-1) items[i].classList.add('active');
      else items[i].classList.remove('active');
    }
  }

  /* ─── Render sweet checkboxes ─── */
  function renderSweet(){
    renderCategory('sweet','sbSweetList',state.sweet,1,updateSweetCount);
  }

  function updateSweetCount(){
    var el = $('sbSweetCount');
    if(el) el.textContent = state.sweet.length;
    var items = document.querySelectorAll('#sbSweetList .sb-check-item');
    for(var i=0;i<items.length;i++){
      var id = items[i].getAttribute('data-id');
      if(state.sweet.indexOf(id)!==-1) items[i].classList.add('active');
      else items[i].classList.remove('active');
    }
  }

  /* ─── Render juice checkboxes ─── */
  function renderJuice(){
    renderCategory('juice','sbJuiceList',state.juice,1,updateJuiceCount);
  }

  function updateJuiceCount(){
    var el = $('sbJuiceCount');
    if(el) el.textContent = state.juice.length;
    var items = document.querySelectorAll('#sbJuiceList .sb-check-item');
    for(var i=0;i<items.length;i++){
      var id = items[i].getAttribute('data-id');
      if(state.juice.indexOf(id)!==-1) items[i].classList.add('active');
      else items[i].classList.remove('active');
    }
  }

  /* ─── Render addon radios ─── */
  function renderAddons(){
    var container = $('sbAddonList');
    if(!container) return;
    var addons = getAddons();
    var html = '';
    for(var i=0;i<addons.length;i++){
      var a = addons[i];
      var checked = state.addon===a.id;
      html += '<label class="sb-radio-item'+(checked?' active':'')+'" data-id="'+esc(a.id)+'">';
      html += '<input type="radio" name="sbAddon" value="'+esc(a.id)+'"'+(checked?' checked':'')+' class="sb-radio-input">';
      html += '<span class="sb-radio-dot"></span>';
      html += '<span class="sb-radio-emoji">'+esc(a.emoji)+'</span>';
      html += '<span class="sb-radio-info">';
      html += '<span class="sb-radio-name">'+esc(a.name)+'</span>';
      html += '<span class="sb-radio-note">'+esc(a.note)+'</span>';
      html += '</span>';
      html += '</label>';
    }
    container.innerHTML = html;

    var inputs = container.querySelectorAll('.sb-radio-input');
    for(var j=0;j<inputs.length;j++){
      inputs[j].addEventListener('change', function(){
        state.addon = this.value;
        var items = container.querySelectorAll('.sb-radio-item');
        for(var k=0;k<items.length;k++){
          if(items[k].getAttribute('data-id')===state.addon) items[k].classList.add('active');
          else items[k].classList.remove('active');
        }
        updateSummary();
      });
    }
  }

  /* ─── Quantity stepper ─── */
  function initQuantity(){
    var num = $('sbQtyNumber');
    var range = $('sbQtyRange');
    var dec = $('sbQtyDec');
    var inc = $('sbQtyInc');
    if(!num) return;

    function setQty(v){
      v = parseInt(v,10)||getMinimumOrder();
      if(v<getMinimumOrder()) v=getMinimumOrder();
      if(v>1000) v=1000;
      state.quantity = v;
      num.value = v;
      if(range) range.value = v;
      updateSummary();
    }

    num.min = getMinimumOrder();
    if(range) range.min = getMinimumOrder();
    setQty(state.quantity);
    num.addEventListener('change', function(){ setQty(this.value); });
    if(range) range.addEventListener('input', function(){ setQty(this.value); });
    if(dec) dec.addEventListener('click', function(){ setQty(state.quantity-5); });
    if(inc) inc.addEventListener('click', function(){ setQty(state.quantity+5); });

    /* quick buttons */
    var quickBtns = document.querySelectorAll('[data-sb-qty]');
    for(var i=0;i<quickBtns.length;i++){
      quickBtns[i].addEventListener('click', function(){
        setQty(parseInt(this.getAttribute('data-sb-qty'),10));
      });
    }
  }

  /* ─── Update summary panel ─── */
  function updateSummary(){
    var pricePerBox = calcPricePerBox();
    var total = calcTotal();
    var addon = getAddonById(state.addon);
    var shipping = getShipping();

    var elBudget = $('sbSumBudget');
    if(elBudget) elBudget.textContent = pricePerBox;

    var elQty = $('sbSumQty');
    if(elQty) elQty.textContent = state.quantity;
    var elQty2 = $('sbSumQty2');
    if(elQty2) elQty2.textContent = state.quantity;

    var elAddon = $('sbSumAddon');
    if(elAddon) elAddon.textContent = addon ? addon.name : 'น้ำเปล่า';

    var elAddonPrice = $('sbSumAddonPrice');
    if(elAddonPrice) elAddonPrice.textContent = addon && addon.price>0 ? '+'+addon.price+'บ' : 'ฟรี';

    var elSweet = $('sbSumSweet');
    if(elSweet){
      var sm = state.sweet.length ? getItemById(state.sweet[0]) : null;
      elSweet.textContent = sm ? sm.name : '— ยังไม่เลือก —';
    }

    var elSavory = $('sbSumSavory');
    if(elSavory){
      var svNames = state.savory.map(function(id){ var m=getItemById(id); return m?m.name:''; }).filter(Boolean);
      elSavory.textContent = svNames.length ? svNames.join(', ') : '— ไม่เลือก (Basik 40บ) —';
    }

    var elJuice = $('sbSumJuice');
    if(elJuice){
      var jm = state.juice.length ? getItemById(state.juice[0]) : null;
      elJuice.textContent = jm ? jm.name : '— ยังไม่เลือก —';
    }

    var elFood = $('sbSumFood');
    if(elFood){
      var savoryCost = 0;
      for(var si=0;si<state.savory.length;si++){
        var sm2 = getItemById(state.savory[si]);
        if(sm2) savoryCost += sm2.price;
      }
      elFood.textContent = (pricePerBox * state.quantity).toLocaleString('th-TH')+' บาท';
    }

    var elShipLabel = $('sbSumShipLabel');
    var elShip = $('sbSumShip');
    if(elShipLabel) elShipLabel.textContent = 'ค่าส่งตามเขต';
    if(elShip) elShip.textContent = shipping.text;

    var elTotal = $('sbSumTotal');
    if(elTotal) elTotal.textContent = total.toLocaleString('th-TH');

    var elAvg = $('sbSumAvg');
    if(elAvg) elAvg.textContent = pricePerBox;

    /* LINE button */
    updateLineLink();
  }

  /* ─── Build LINE message ─── */
  function buildMessage(){
    var lines = [];
    lines.push('📦 สั่ง Snack Box ฮาลาล');
    lines.push('');
    var savoryCost = 0;
    for(var si=0;si<state.savory.length;si++){
      var sm = getItemById(state.savory[si]);
      if(sm) savoryCost += sm.price;
    }
    var basePrice = calcPricePerBox();
    lines.push('💰 งบต่อกล่อง: '+basePrice+' บาท');
    lines.push('📦 จำนวน: '+state.quantity+' กล่อง');
    lines.push('📍 เขตจัดส่ง: '+(state.deliveryZone && typeof EED!=='undefined' ? EED.shippingZones[state.deliveryZone].label : 'ยังไม่ระบุ'));
    lines.push('');

    if(state.savory.length){
      var savNames = state.savory.map(function(id){
        var m=getItemById(id);
        return m ? '• '+m.name+' (+'+m.price+'บ)' : '';
      }).filter(Boolean);
      lines.push('🥐 ของว่างคาว:');
      lines.push(savNames.join('\n'));
      lines.push('');
    }

    if(state.sweet.length){
      var sweetM = getItemById(state.sweet[0]);
      if(sweetM) lines.push('🍰 ของหวาน: • '+sweetM.name);
      lines.push('');
    }

    if(state.juice.length){
      var juiceM = getItemById(state.juice[0]);
      if(juiceM) lines.push('🧃 น้ำผลไม้: • '+juiceM.name);
      lines.push('');
    }

    var addon = getAddonById(state.addon);
    if(addon){
      lines.push('☕ เครื่องดื่ม: '+addon.name+(addon.price>0?' (+'+addon.price+'บ)':' (ฟรี)'));
      lines.push('');
    }

    var shipping=getShipping();
    lines.push('🚚 ค่าส่ง: '+shipping.text);
    lines.push('💵 ราคารวม: '+calcTotal().toLocaleString('th-TH')+' บาท');
    lines.push('('+basePrice+' x '+state.quantity+(shipping.fee?' + ค่าส่ง '+shipping.fee+'บ':'')+')');
    lines.push('');
    lines.push('📊 ข้อมูลนี้คำนวณจากระบบ — ราคาสุดท้ายทีมงานยืนยันครับ');

    return lines.join('\n');
  }

  function updateLineLink(){
    var btn = $('sbLineBtn');
    if(!btn) return;
    btn.href = LINE_URL;
    btn.onclick = function(e){
      var msg = buildMessage();
      if(navigator.clipboard){
        navigator.clipboard.writeText(msg).then(function(){
          showToast('สรุปถูกคัดลอกแล้ว! วางใน LINE ได้เลย ✓');
        });
      } else {
        var ta = document.createElement('textarea');
        ta.value = msg;
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        showToast('สรุปถูกคัดลอกแล้ว! วางใน LINE ได้เลย ✓');
      }
    };
  }

  /* ─── Copy summary ─── */
  function copySummary(){
    var msg = buildMessage();
    if(navigator.clipboard){
      navigator.clipboard.writeText(msg).then(function(){
        showToast('คัดลอกแล้ว! วางใน LINE ได้เลย ✓');
      });
    } else {
      var ta = document.createElement('textarea');
      ta.value = msg;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand('copy');
      document.body.removeChild(ta);
      showToast('คัดลอกแล้ว! วางใน LINE ได้เลย ✓');
    }
  }

  function showToast(text){
    var el = $('sbCopyToast');
    if(!el) return;
    el.textContent = text;
    el.style.display = 'block';
    setTimeout(function(){ el.style.display='none'; }, 2500);
  }

  /* ─── Init ─── */
  function init(){
    if(typeof EED_SNACK_MENUS==='undefined') return;
    renderDeliveryZones();
    renderSweet();
    renderSavory();
    renderJuice();
    renderAddons();
    initQuantity();
    updateSummary();

    document.addEventListener('snackCatalogHydrated', function(){
      renderDeliveryZones();
      renderSweet();
      renderSavory();
      renderJuice();
      renderAddons();
      updateSummary();
    });

    var copyBtn = $('sbCopySummary');
    if(copyBtn) copyBtn.addEventListener('click', copySummary);
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

