test('snack box builder updates summary in a browser-like context', () => {
  const ids = [
    'sbDeliveryZone', 'sbSweetList', 'sbSavoryList', 'sbJuiceList', 'sbAddonList',
    'sbSweetCount', 'sbSavoryCount', 'sbJuiceCount', 'sbQtyNumber', 'sbQtyRange',
